<template><section class="ops-workbench"><div class="page-head"><div><h2>{{config.title}}</h2><p class="sub">按实际工序和交接状态办理；申请与处理保留原单据记录。</p></div><button class="btn btn-ghost" @click="load">刷新列表</button></div><div class="ops-actions"><router-link v-for="a in config.actions.filter(a=>canVisit(a[1]))" :key="a[0]" :to="a[1]" class="btn btn-ghost">{{a[0]}}</router-link></div><div class="ops-scopes"><button v-for="m in modes" :key="m[0]" :class="{on:mode===m[0]}" @click="mode=m[0];queue='all'">{{m[1]}}</button></div><div class="ops-queues"><button :class="{on:queue==='all'}" @click="queue='all'">全部 {{scoped.length}}</button><button v-for="t in config.queues" :key="t[0]" :class="{on:queue===t[0]}" @click="queue=t[0]">{{t[1]}} {{scoped.filter(r=>match(r,t[0])).length}}</button></div><div class="ops-search"><b>生产订单 {{filtered.length}} 单</b><input class="input" v-model="search" placeholder="订单号 / 款号 / 客户"/><span v-if="error" role="alert">{{error}}</span></div><div class="ops-scroll"><table><thead><tr><th>订单信息</th><th>生产方式</th><th>当前进度</th><th>货期</th><th>客户</th><th>业务员</th><th>接单工厂</th><th>裁片外发</th><th>操作</th></tr></thead><tbody><tr v-for="r in filtered.slice((page-1)*size,page*size)" :key="r.id"><td class="ops-order"><img v-if="r.thumb" :src="r.thumb" @click="openImage(r.thumb,r.order_no)"/><button class="link-btn" @click="router.push({path:'/orders',query:{order:r.id}})">{{r.style_name||r.order_no}}<small>{{r.order_no}}</small></button></td><td>{{r.cut_dispatches?'裁片外发':'本厂生产'}}</td><td>{{r.current||'暂无待办工序'}}<small>{{r.done_count}} / {{r.total_count}} 节点完成</small></td><td>{{r.delivery_date||'—'}}</td><td>{{r.customer_name||'—'}}</td><td>{{r.manager||'—'}}</td><td>{{r.assign_names||'—'}}</td><td>{{r.cut_factory_names||'—'}}</td><td><button class="link-btn" @click="router.push({path:'/orders',query:{order:r.id}})">订单详情</button><button v-if="activeNode(r)?.node_id" class="link-btn" @click="nodeId=activeNode(r).node_id;panelOpen=true">办理当前工序</button></td></tr><tr v-if="!filtered.length"><td colspan="9" class="empty-cell">{{error?'数据读取失败，请重试':'此范围暂无订单'}}</td></tr></tbody></table></div><ReferencePager v-model:page="page" v-model:page-size="size" :total="filtered.length" @refresh="load"/><NodePanel v-model:open="panelOpen" :node-id="nodeId" @changed="load"/></section></template>
<script setup>
import {ref,computed,watch,onMounted} from 'vue';import {useRouter} from 'vue-router';import {api} from '../api';import {openImage} from '../store/viewer';import {canVisit} from '../store/navigation';import ReferencePager from './ReferencePager.vue';import NodePanel from './NodePanel.vue';
const props=defineProps({station:String}),router=useRouter(),rows=ref([]),mode=ref('all'),queue=ref('all'),search=ref(''),page=ref(1),size=ref(12),error=ref('');
const panelOpen=ref(false),nodeId=ref(null);function activeNode(r){return [...(r.cells||[]),...(r.extra||[])].find(n=>n.code===r.current_code&&!n.missing);}
const common=[['异常登记与处理','/exceptions'],['订单跟踪','/order-tracking']];
const configs={cut:{title:'裁床',queues:[['layout','待算料订单'],['issue','待领料订单'],['cut','待裁订单'],['exception','异常登记与处理']],actions:[['申请领料','/material-flow'],...common],action:'/cuts',actionLabel:'办理用量 / 裁剪'},warehouse:{title:'前端仓库',queues:[['fabric','原料待入库'],['accessory','辅料待入库'],['delivery','待配出辅料'],['exception','异常登记与处理']],actions:[['原料待入库','/receipts'],['辅料待入库','/receipts'],['裁床申请','/material-flow'],['缝制申请','/material-flow'],['库位与批次','/material-flow'],...common],action:'/material-flow',actionLabel:'备料 / 发料'},workshop:{title:'车间',queues:[['sew','在产订单明细'],['exception','异常申请']],actions:[['领片申请','/cuts'],['异常申请','/exceptions'],['工序报工','/scan']],action:'/scan',actionLabel:'扫码报工'},finish:{title:'后整',queues:[['finish','后整在产明细'],['inspect','质检明细'],['instock','入库明细'],['exception','异常申请']],actions:[['异常申请','/exceptions'],['工艺外发','/cut-dispatch'],['返工登记','/production-close'],['发货申请','/orders'],['质检明细','/quality'],['入库明细','/inventory']],action:'/orders',actionLabel:'办理订单交付'}};
const config=computed(()=>configs[props.station]||configs.cut),modes=computed(()=>props.station==='workshop'?[['all','全部'],['own','本厂生产']]:[['all','全部'],['own','本厂生产'],['cut','裁片外发']]);
const scoped=computed(()=>rows.value.filter(r=>r.assign_mode!=='outsource'&&(mode.value!=='own'||!r.cut_dispatches)&&(mode.value!=='cut'||r.cut_dispatches>0)&&(props.station!=='workshop'||!r.cut_dispatches)));
function match(r,key){const nodes=[...(r.cells||[]),...(r.extra||[])],pending=code=>r.current_code===code&&nodes.some(n=>n.code===code&&!n.missing&&!['done','skipped','none'].includes(n.status));if(key==='exception')return r.exception_count>0||r.rework_count>0;if(key==='issue')return nodes.some(n=>/领料/.test(n.name)&&n.code===r.current_code&&!n.missing&&!['done','skipped','none'].includes(n.status));if(key==='fabric'||key==='accessory')return nodes.some(n=>(n.panel==='purchase_'+key||new RegExp(key==='fabric'?'面料采购':'辅料采购').test(n.name))&&n.code===r.current_code&&!n.missing&&!['done','skipped','none'].includes(n.status));if(key==='delivery')return nodes.some(n=>/辅料配送/.test(n.name)&&n.code===r.current_code&&!n.missing&&!['done','skipped','none'].includes(n.status));if(key==='finish')return pending('iron')||pending('pack');return pending(key);}
const filtered=computed(()=>scoped.value.filter(r=>(queue.value==='all'||match(r,queue.value))&&(!search.value||[r.order_no,r.style_name,r.customer_name].some(s=>String(s||'').toLowerCase().includes(search.value.trim().toLowerCase())))));
async function load(){error.value='';try{const d=await api.nodeFlowBoard({tracking:1,tracking_view:'factory',limit:5000});rows.value=d.rows||[];}catch(e){error.value=e.message;rows.value=[];}}
watch(()=>props.station,()=>{mode.value='all';queue.value='all';page.value=1;});watch([mode,queue,search],()=>page.value=1);onMounted(load);
</script><style scoped>.ops-workbench{padding:4px}.ops-actions,.ops-scopes,.ops-queues{display:flex;gap:10px;flex-wrap:wrap;padding:14px;border:1px solid var(--line);background:var(--surface)}.ops-scopes{background:var(--surface-2)}.ops-scopes button,.ops-queues button{padding:9px 20px;border:1px solid var(--line);background:var(--surface);color:var(--ink);border-radius:3px;cursor:pointer}.ops-scopes .on,.ops-queues .on{background:var(--brand);color:white;border-color:var(--brand)}.ops-search{display:flex;align-items:center;gap:16px;padding:18px;background:var(--surface)}.ops-search input{margin-left:auto;width:260px}.ops-scroll{overflow:auto;background:var(--surface);margin-bottom:12px}table{width:100%;min-width:1100px;border-collapse:collapse;font-size:12px}th,td{padding:16px;border:1px solid var(--line);text-align:left}th{background:var(--surface-2)}td{height:110px}.ops-order{display:flex;align-items:center;gap:12px}.ops-order img{width:64px;height:84px;object-fit:contain;cursor:zoom-in}small{display:block;color:var(--ink-mute);font-size:11px;margin-top:8px}td:last-child .link-btn{display:block;margin:8px 0}</style>
